import{z as s,x as h,o as l,c as B,q as n,j as o,D as e,d as r,s as E,S as p,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"淬灭剂中和动力学","description":"","frontmatter":{"title":"淬灭剂中和动力学","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/quencher-neutralization.md","filePath":"litho/quencher-neutralization.md","lastUpdated":1791413859000}'),A={name:"litho/quencher-neutralization.md"};function d(q,a,_,D,c,m){const i=h("Mermaid");return l(),B("div",null,[a[2]||(a[2]=n('<h1 id="淬灭剂中和动力学" tabindex="-1">淬灭剂中和动力学 <a class="header-anchor" href="#淬灭剂中和动力学" aria-label="Permalink to &quot;淬灭剂中和动力学&quot;">​</a></h1><div class="epigraph"><p>碱不是背景常数：它与酸双分子湮灭，边沿的争夺带宽度由中和速率与扩散一起决定。</p><footer>—— 据 Mack 对产酸–中和阈值的表述；配方侧见 PAG / 淬灭剂对</footer></div><p><a href="/litho/peb-reaction-diffusion">上一课</a>写出了酸的扩散与催化，却把汇写成省略号。<a href="/litho/pag-quencher">PAG 与淬灭剂</a>和<a href="/litho/quencher-loading">淬灭剂负载</a>已经把碱钉成阈值库存。缺口是动力学：中和多快、是否扩散限制、争夺带如何进衬度。本课补 \\(k_q h q\\)。显影速率如何切这张脱保护场，留给<a href="/litho/development-rate-model">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有效酸「\\(\\approx\\) 生成酸 \\(-\\) 碱」是积分守恒的口语。PEB 期间酸与淬灭剂都在走，局部湮灭</p> \\[\\frac{\\partial h}{\\partial t}=\\nabla\\cdot(D_h\\nabla h)-k_q h q,\\qquad \\frac{\\partial q}{\\partial t}=\\nabla\\cdot(D_q\\nabla q)-k_q h q \\]<p>才是场方程。\\(k_q\\) 很大时，中和几乎一遇即灭，前沿变成酸碱相遇的反应面，有效 \\(\\ell\\) 被库存比压短——负载课说过的「争夺带变窄」，现在有速率。\\(k_q\\) 有限时，酸可以穿过碱区一段再灭，核更胖，暗区漏催化。</p><p>缺口不是再定义淬灭剂，而是：阈值轮廓是中和动力学的等值面，不是光学 \\(I_\\mathrm{th}\\) 的别名。</p><p><span class="marginnote">术语翻译：「双分子湮灭」就是一个酸分子和一个碱分子相遇即同归于尽，速率正比于两者浓度之积 \\(k_q h q\\)——像两支相向行进的队伍，碰上就双双出局。负载课里的「争夺带」，现在有了速率这个角色。</span></p><h3 id="光可分解淬灭剂只改初值" tabindex="-1">光可分解淬灭剂只改初值 <a class="header-anchor" href="#光可分解淬灭剂只改初值" aria-label="Permalink to &quot;光可分解淬灭剂只改初值&quot;">​</a></h3><p>某些配方让曝光区的碱自己分解，亮区 \\(q\\) 初值低于暗区。动力学形式不变，只是 \\(q(x,0)\\) 不再均匀。本课承认这种不对称，不写分子式。不要把它当成另一种光学对比度。</p><p><span class="marginnote">环境胺是从表面进来的额外 \\(q\\)，造成 T-top。那是边界条件，不是本体 \\(k_q\\) 的标定。延迟 PEB 让表面淬灭有时间深入，看起来像「中和变快」，根子是等待，不是速率常数漂了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拟合：固定 PAG，扫负载，看 \\(E_0\\)、侧壁与 LWR；再扫 PEB \\(T\\)，看争夺带是否随 \\(D_h/D_q\\) 变。若 CD 只随库存比走、几乎不随 PEB 时间在中和段变化，可取瞬时中和极限，方程降阶。若暗区起雾对 PEB 时间敏感，必须保留有限 \\(k_q\\)。</p><p>与酸扩散课的接口：淬灭剂缩短有效 \\(\\ell\\)，是本课湮灭项的后果，不是另加一颗独立核。OPC 紧凑模型若只有一颗高斯、没有碱项，换负载等于整颗核重拟合。</p><p><span class="marginnote">数字实例：若实测发现「CD 只随 PAG/碱摩尔比走、几乎不随 PEB 时间在中和段变化」，就能取瞬时中和极限，把场方程降阶——少一个待拟合参数；反之暗区起雾对 PEB 时间敏感，\\(k_q\\) 必须保留为有限值，模型多一个自由度也多一次标定成本。</span></p>',16)),(l(),o(p,null,{default:e(()=>[E(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%85%B8%20h%22%5D%20--%3E%20KQ%5B%22k_q%20h%20q%20%E4%B8%AD%E5%92%8C%22%5D%0A%20%20Q%5B%22%E6%B7%AC%E7%81%AD%E5%89%82%20q%22%5D%20--%3E%20KQ%0A%20%20KQ%20--%3E%20BAND%5B%22%E8%BE%B9%E6%B2%BF%E4%BA%89%E5%A4%BA%E5%B8%A6%22%5D%0A%20%20DH%5B%22D_h%20%2F%20D_q%22%5D%20--%3E%20BAND%0A%20%20BAND%20--%3E%20M%5B%22%E8%84%B1%E4%BF%9D%E6%8A%A4%E9%98%88%E5%80%BC%E9%9D%A2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"亮区中心酸远多于碱，碱先被灭光，催化按上一课的 \\(k_a h m\\) 全速。暗区碱远多于酸，酸进得去也活不久，\\(m\\) 几乎不动。边沿两者相当，反应面的位置随剂量（酸总量）移动——这就是化学阈值。Mack 把光学强度映射到这条面上；NILS 决定面随剂量横移多少，中和动力学决定面有多薄。",-1)),a[5]||(a[5]=t("p",null,"碱分子若比酸大，\\(D_q\\) 更小，反应面更靠暗区一侧被酸「推」着走。负载升高，推到同一 CD 需要更多酸，灵敏度下降。这与配方课同一句话，本课指出执行它的是 \\(k_q\\) 与两套 \\(D\\)。",-1)),(l(),o(p,null,{default:e(()=>[E(i,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%85%B8%E5%90%91%E6%9A%97%E5%8C%BA%E6%89%A9%E6%95%A3%22%5D%20--%3E%20R%7B%22k_q%20%E5%A4%A7%E5%B0%8F%22%7D%0A%20%20R%20--%3E%7C%22k_q%20%E5%BE%88%E5%A4%A7%22%7C%20SURF%5B%22%E4%B8%80%E9%81%87%E5%8D%B3%E7%81%AD%EF%BC%9A%E5%8F%8D%E5%BA%94%E9%9D%A2%E6%B8%85%E6%99%B0%22%5D%0A%20%20R%20--%3E%7C%22k_q%20%E6%9C%89%E9%99%90%22%7C%20PASS%5B%22%E9%85%B8%E7%A9%BF%E8%BF%87%E7%A2%B1%E5%8C%BA%E4%B8%80%E6%AE%B5%E5%86%8D%E7%81%AD%22%5D%0A%20%20SURF%20--%3E%20THIN%5B%22%E4%BA%89%E5%A4%BA%E5%B8%A6%E7%AA%84%EF%BC%8C%E9%98%88%E5%80%BC%E9%99%A1%22%5D%0A%20%20PASS%20--%3E%20FAT%5B%22%E6%A0%B8%E5%8F%98%E8%83%96%EF%BC%8C%E6%9A%97%E5%8C%BA%E6%BC%8F%E5%82%AC%E5%8C%96%E8%B5%B7%E9%9B%BE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：初学者容易以为「扩散核是一颗固定的高斯，换负载只是平移阈值」。实际上负载与 \\(k_q\\) 通过湮灭项改的是核宽本身——换一次负载等于换一颗核，紧凑模型必须整体重拟合，而不是把阈值挪一挪了事。</span></p><p><span class="marginnote">EUV 事件稀疏时，碱分子计数本身成为随机源，连续场 \\(q\\) 会撒谎。那是<a href="/litho/acid-quencher-counting">酸与淬灭剂计数</a>的缺口；本课平均场仍然成立，作为后课抽样的均值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不报某配方的 \\(k_q\\) 数值当宇宙常数。负胶交联体系碱仍在收酸，留下的区域符号相反。酸放大器会额外产酸，中和零点还在，联合标定必须重做——主干<a href="/litho/acid-amplifier">酸放大器</a>已警告过，本课不重开那一节。</p><p>下一课默认脱保护场 \\(m(x,z)\\) 已经含中和，再问溶解速率 \\(R(m)\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中和是双分子湮灭，争夺带宽度由 \\(k_q\\) 与 \\(D_h\\)、\\(D_q\\) 决定。</li><li>「生成酸 \\(-\\) 碱」是守恒口语；轮廓是反应面。</li><li>瞬时中和极限给出更陡阈值、更短有效 \\(\\ell\\)。</li><li>环境胺是边界 \\(q\\)，不要并进本体 \\(k_q\\)。</li><li>平均场 \\(q\\) 是后课计数噪声的均值。</li><li>出处：Mack 对产酸–中和；<a href="/litho/pag-quencher">PAG 与淬灭剂</a>的库存语言。</li></ul>',7))])}const k=s(A,[["render",d]]);export{f as __pageData,k as default};
